def solution(input_data):
    """
    Solves the Jeel and Ashish matrix game problem.
    Each non-zero value contributes to an XOR sum - if non-zero, Ashish wins, else Jeel.
    """
    lines = input_data.strip().split('\n')
    idx = 0
    t = int(lines[idx])
    idx += 1
    results = []

    for _ in range(t):
        n, m = map(int, lines[idx].split())
        idx += 1
        xor_sum = 0
        for i in range(n):
            row = list(map(int, lines[idx].split()))
            idx += 1
            for val in row:
                if val > 0:
                    xor_sum ^= val

        if xor_sum == 0:
            results.append("Jeel")
        else:
            results.append("Ashish")

    return '\n'.join(results)

