def solve(n):
    primes = get_prime_factors(n)
    divs = get_divisors(n)

    # For n with 1 or 2 divisors, they can be arranged with 0 moves  
    # (since any pair of divisors can be adjacent with 0 moves if not coprime)
    if len(divs) == 1:
        return [divs[0]], 0

    # Build order to minimize moves
    # If n has at least 2 prime factors, try to arrange optimally

    # Strategy: group divisors by their prime factors
    primes_list = sorted(primes)

    # Try to arrange: place divisors in sequence so gcd(adjacent) > 1

    result = []
    used = set()

    # Divide into groups by prime
    def assign_to_groups(d):
        for p in primes_list:
            if d % p == 0:
                return p
        return primes_list[0]

    groups = {p: [] for p in primes_list}
    for d in divs:
        groups[assign_to_groups(d)].append(d)

    # Build order by going around primes
    # Add all divisors whose smallest prime is current prime
    current = primes_list[0]

    # Construct: start with one prime group, then others, end with final prime group
    # This ensures most adjacencies share a prime

    if len(primes_list) == 1:
        return divs, 0  # Only divisors are multiples of same prime

    if len(primes_list) == 2:
        # Two primes p, q: if p != q and both are in divisors
        # divisors of n = p^a * q^b
        # divisors > 1 include: p, q, p*q, p^2, p*q*..., q^2, ...
        # Any arrangement with n in between p and q works better?
        # Actually gcd(n, p) = p > 1, gcd(n, q) = q > 1
        # gcd(p, q) = 1 (since distinct primes)

        # To minimize moves, place n between p and q
        # Start with [p, n, q] then fill rest

        # Better: arrange as [p, n, q, p^2, n*q, q^2, ...] where gcds work

        # Simple approach: use max element to bridge gaps
        # Put largest divisor at start

        order = [divs[-1]]  # largest divisor
        visited = {divs[-1]}

        # Build greedily
        divs_list = sorted(divs)

        for d in divs_list:
            if d in visited:
                continue
            for last in order:
                if gcd(last, d) > 1:
                    order.append(d)
                    visited.add(d)
                    break

            if d not in visited:
                # No valid position found, just append at end
                order.append(d)
                visited.add(d)

        # Check circular
        for i in range(len(order)):
            adj1, adj2 = order[i], order[(i + 1) % len(order)]
            if gcd(adj1, adj2) == 1:
                return order, 1

        return order, 0

    # 3+ primes: try to arrange so gcd(2,3) issue doesn't matter
    # Use all divisors, arrange greedily

    order = []
    visited = set()

    # Special: if n has at least 3 primes, gcd(n, any_prime_divisor) > 1
    # So n can serve as bridge

    # Greedy: always pick divisors that connect via shared prime
    def find_valid_neighbor(last_divisor):
        for d in divs:
            if d in visited:
                continue
            if gcd(last_divisor, d) > 1:
                return d
        return None

    # Start with largest divisor (contains all primes)
    order.append(divs[-1])
    visited.add(divs[-1])

    for _ in range(len(divs) - 1):
        new_div = find_valid_neighbor(order[-1])
        if new_div:
            order.append(new_div)
            visited.add(new_div)
        else:
            # No valid connection, add unvisited to end
            for d in divs:
                if d not in visited:
                    order.append(d)
                    visited.add(d)
                    break

    # Calculate moves needed
    moves = 0
    for i in range(len(order)):
        adj1, adj2 = order[i], order[(i + 1) % len(order)]
        if gcd(adj1, adj2) == 1:
            moves += 1

    return order, moves

