    lines = input_str.strip().split('\n')
    n_k = lines[0].split()
    n, k = int(n_k[0]), int(n_k[1])
    s = lines[1]

    # Edge case: k is larger than n
    if k > n:
        return "NO\n"

    # Case k=0: No 'N's allowed, all must be 'Y'
    if k == 0:
        if 'N' in s:
            return "NO\n"
        return "YES\n"

    def can_make_exactly_k(start):
        """Check if we can make exactly k consecutive N's starting at position start."""
        # Check if positions [start, start+k-1] can all be N (no Y in range)
        for i in range(start, start + k):
            if s[i] == 'Y':
                return False

        # Now try to fill the rest to ensure max consecutive N = k
        # We'll use a greedy approach: make ? into Y whenever adding N would exceed k

        current_consecutive = [0] * (n + 1)

        for i in range(n):
            if i >= start and i < start + k:
                # This is part of our k consecutive N's
                current_consecutive[i+1] = current_consecutive[i] + 1
            elif s[i] == 'N':
                # Fixed N
                current_consecutive[i+1] = current_consecutive[i] + 1
            else:  # s[i] == 'Y' or we chose Y for ?
                current_consecutive[i+1] = 0

        # Check if any sequence exceeds k
        max_consecutive = max(current_consecutive)
        if max_consecutive > k:
            return False

        return True

    # Try each possible starting position for k consecutive N's
    for start in range(n - k + 1):
        if can_make_exactly_k(start):
            return "YES\n"

    return "NO\n"

