    def manhattan(d1, d2):
        return abs(d1[0] - d2[0]) + abs(d1[1] - d2[1])

    def get_time_for_point(p):
        if not dwarves:
            return 0

        max_time = 0

        if not stations:
            # No subway - each dwarf walks directly to p
            for d in dwarves:
                max_time = max(max_time, manhattan(d, p))
        else:
            # Each dwarf can either walk directly OR use subway
            for d in dwarves:
                # Option 1: Walk directly from dwarf to p
                direct_time = manhattan(d, p)

                # Option 2: Use subway system
                # Find best approach: either all stations help or none
                best_through_subway = float('inf')
                for s in stations:
                    inbound = manhattan(d, s)  # dwarf to station
                    outbound = manhattan(s, p)  # station to gathering point
                    best_through_subway = min(best_through_subway, inbound + outbound)

                # Dwarf takes minimum path
                dwarf_cost = min(direct_time, best_through_subway)
                max_time = max(max_time, dwarf_cost)

        return max_time

    if not stations:
        # No subway available - find optimal pure walking point
        if not dwarves:
            return "0\n"

        sorted_x = sorted([d[0] for d in dwarves])
        sorted_y = sorted([d[1] for d in dwarves])

        # Median minimizes Manhattan distance sum
        mid_x = sorted_x[len(sorted_x) // 2]
        mid_y = sorted_y[len(sorted_y) // 2]

