def is_gp(arr):
    """Check if array is a geometric progression."""
    n = len(arr)
    if n <= 1:
        return True

    # All zeros is always a GP
    if all(x == 0 for x in arr):
        return True

    # If first element is 0, all elements must be 0 for it to be a GP
    if arr[0] == 0:
        for x in arr:
            if x != 0:
                return False
        return True

    # arr[0] != 0, so we can compute ratio from first two elements
    # Use a tolerance for floating point comparison
    ratio = arr[1] / arr[0]
    tolerance = 1e-9

    # Check each consecutive pair against the ratio
    for i in range(2, n):
        if abs(arr[i] - ratio * arr[i-1]) > tolerance * abs(ratio * arr[i-1]) if ratio != 0 else abs(arr[i]):
            return False

    return True

