class DinicFlow:
    def __init__(self, n):
        self.adj = [[] for _ in range(n)]
        self.level = [0] * n

    def add_edge(self, u, v, capacity):
        self.adj[u].append([v, len(self.adj[v]), capacity])
        self.adj[v].append([u, len(self.adj[u]) - 1, 0])

    def bfs(self, s, t):
        self.level = [-1] * len(self.adj)
        queue = [s]
        self.level[s] = 0
        while queue:
            u = queue.pop(0)
            for v, cap, residual in self.adj[u]:
                if self.level[v] < 0 and residual > 0:
                    self.level[v] = self.level[u] + 1
                    queue.append(v)
        return self.level[t] >= 0

    def dfs(self, u, flow, t, ptr):
        if u == t or flow == 0:
            return flow
        for i in range(ptr[u], len(self.adj[u])):
            ptr[u] = i
            v, rev, residual = self.adj[u][i][0], self.adj[u][i][1], self.adj[u][i][2]
            if self.level[v] == self.level[u] + 1 and residual > 0:
                pushed = self.dfs(v, min(flow, residual), t, ptr)
                if pushed > 0:
                    self.adj[u][i][2] -= pushed
                    self.adj[v][rev][2] += pushed
                    return pushed
        return 0

    def max_flow(self, s, t):
        flow = 0
        while self.bfs(s, t):
            ptr = [0] * len(self.adj)
            while True:
                pushed = self.dfs(s, float('inf'), t, ptr)
                if pushed == 0:
                    break
                flow += pushed
        return flow


