def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ''

    n, m = int(lines[0].split()[0]), int(lines[0].split()[1])

    if m == n - 1:
        return ''

    edges = []
    for i in range(m):
        parts = list(map(int, lines[i + 1].split()))
        u, v, w = parts[0], parts[1], parts[2]
        edges.append((u, v, w, i))

    # Union-Find for Kruskal's
    parent = list(range(n + 1))
    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py
            return True
        return False

    # Build MST
    mst_adj = [[] for _ in range(n + 1)]
    edges_by_w = sorted(edges, key=lambda x: x[2])

    for u, v, w, i in edges_by_w:
        if union(u, v):
            mst_adj[u].append((v, w))
            mst_adj[v].append((u, w))

    # Build LCA structure with binary lifting
    LOG = 20
    up = [[0] * (n + 1) for _ in range(LOG)]
    max_edge = [[0] * (n + 1) for _ in range(LOG)]
    depth = [0] * (n + 1)
    visited = [False] * (n + 1)

    # DFS for tree processing
    stack = [(1, 0, 0)]  # (u, parent, w_from_parent)
    visited[1] = True

    while stack:
        u, p, wP = stack.pop()

        # Build up table at this depth
        up[0][u] = p
        max_edge[0][u] = wP

        for i in range(1, LOG):
            if up[i-1][u] != 0:
                up[i][u] = up[i-1][up[i-1][u]]
                max_edge[i][u] = max(max_edge[i-1][u], max_edge[i-1][up[i-1][u]])
            else:
                up[i][u] = 0
                max_edge[i][u] = max_edge[i-1][u]

        for v, w in mst_adj[u]:
            if not visited[v]:
                visited[v] = True
                stack.append((v, u, w))
                depth[v] = depth[u] + 1

    def query_max(u, v):
        if depth[u] < depth[v]:
            u, v = v, u

        result = 0
        for i in range(LOG - 1, -1, -1):
            if depth[u] - (1 << i) >= depth[v]:
                if u != 0:
                    result = max(result, max_edge[i][u])
                    u = up[i][u]

        if u == v:
            return result

        for i in range(LOG - 1, -1, -1):
            if up[i][u] != up[i][v]:
                if u != 0:
                    result = max(result, max_edge[i][u])
                if v != 0:
                    result = max(result, max_edge[i][v])
                u = up[i][u]
                v = up[i][v]

        if u != 0:
            result = max(result, max_edge[0][u])
            u = up[0][u]
        if v != 0:
            result = max(result, max_edge[0][v])
            v = up[0][v]

        return result

    # Process non-MST edges
    output = []
    for u, v, w, orig_idx in edges:
        if v != 0:
            mx = query_max(u, v)
            output.append(mx)

    return '\n'.join(map(str, output))

