from functools import lru_cache

@lru_cache(maxsize=None)
def grundy(n, k):
    """Computes Grundy number for a pile of size n with parameter k."""
    if n == 0:
        return 0

    # For odd n, we can only remove 1 cow (go to n-1)
    if n % 2 == 1:
        return grundy(n - 1, k)

    # For even n = 2x, we can:
    # 1. Remove 1 cow -> go to n-1
    # 2. Split into k piles of x cows each

    # Calculate both options
    op1 = grundy(n - 1, k)

    # For split: k piles of size n/2
    # XOR of k copies of g(n/2) is g(n/2) if k is odd, 0 if k is even
    if k % 2 == 1:
        op2 = grundy(n // 2, k)
    else:
        op2 = 0

    # mex(gives minimum excluded value)
    reachable = {op1, op2}
    mex = 1
    while mex in reachable:
        mex += 1
    return mex

