    def can_be_palindrome(s):
        from collections import Counter
        freq = Counter(s)
        return sum(1 for f in freq.values() if f % 2 == 1) <= 1

    count = 0

    # Iterate over all submatrices [i1..i2] x [j1..j2]
    for i1 in range(n):
