            for j1 in range(m):
                for j2 in range(j1, m):
                    # Check all rows in this submatrix
                    rows_good = True
                    for i in range(i1, i2+1):
                        row_str = matrix[i][j1:j2+1]
                        if not can_be_palindrome(row_str):
                            rows_good = False
                            break
                    if not rows_good:
                        continue

                    # Check all columns in this submatrix
                    cols_good = True
                    for j in range(j1, j2+1):
                        col_chars = []
                        for i in range(i1, i2+1):
