    def try_find_paths(s, t):
        used = [[False] * (n + 1) for _ in range(3)]

        # Find each path ensuring node and edge disjointness
        paths = []

        for k in range(3):
            if k == 0:
                visited = {s}
                parent = {}
                queue = [s]
                found = False

                while queue:
                    u = queue.pop(0)
                    if u == t:
                        found = True
                        paths.append(reconstruct(k, parent, t))
                        break

                    for v in adj[u]:
                        if v not in visited:
                            visited.add(v)
                            parent[k, v] = u
                            queue.append(v)
                if not found:
                    return None
            else:
                # Mark internal nodes of previous paths as unavailable
                for k2 in range(k):
                    pn = set(paths[k2][1:-1])  # intermediate nodes
                    if any(x in pn for x in paths[k]):
                        return None

                # Try BFS avoiding flagged nodes
                blocked = set()
                for other_path in paths[:k]:
                    # Cannot reuse intermediate nodes or edges
                    for node in other_path[1:-1]:
                        blocked.add(node)
                    for i in range(len(other_path)-1):
                        u, v = other_path[i], other_path[i+1]
                        blocked.add(edge_key(u, v))

                visited = {s}
                parent = {}
                queue = [s]
                found = False

                while queue:
                    u = queue.pop(0)
                    if u == t:
                        found = True
                        paths.append(reconstruct(k, parent, t))
                        break

                    for v in adj[u]:
                        if v not in visited and v not in blocked and v != s:
                            visited.add(v)
                            parent[k, v] = u
                            queue.append(v)
                if not found:
                    return None

        # Verify all paths are truly disjoint
        if not verify_paths(paths):
            return None

        return paths

    def edge_key(u, v):
        return (min(u, v), max(u, v))

    def reconstruct(k, parent, target):
        path = []
