def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    target = math.ceil(math.sqrt(n))

    adj = [[] for _ in range(n + 1)]
    for line in lines[1:]:
        u, v = map(int, line.split())
        adj[u].append(v)
        adj[v].append(u)

    result = None

    # Global tracking: color 0=unvisited, 1=visiting, 2=processed
    color = [0] * (n + 1)
    parent = {}
    depth = {}

    def dfs_find_cycle(node):
        nonlocal result
        color[node] = 1  # Visiting

        for neighbor in adj[node]:
            if color[neighbor] == 1:  # Back edge found (cycle)
                # Reconstruct cycle by tracing back through parent pointers
                cycle = []
                curr = node
                while curr != neighbor:
                    cycle.append(curr)
                    curr = parent[curr]
                cycle.append(neighbor)
                cycle.reverse()

                if len(cycle) >= target:
                    result = ("2", len(cycle), " ".join(map(str, cycle)))
                    return True
            elif color[neighbor] == 0:  # Unvisited, go deeper
                parent[neighbor] = node
                depth[neighbor] = depth[node] + 1
                if dfs_find_cycle(neighbor):
                    return True

        color[node] = 2  # Processed
        return False

    # Try DFS from first node (graph is connected)
    if dfs_find_cycle(1):
        return result[1] + "\n" + result[2] + "\n"

    # Main solution logic
    # If no long cycle found, must find large independent set

    # Greedy independent set: nodes sorted by degree
    nodes = list(range(1, n + 1))
    nodes.sort(key=lambda x: len(adj[x]))

    indep_set = []
    filtered = set()  # Track nodes that can't be added

    for node in nodes:
        if node in filtered:
            continue
        if len(indep_set) >= target:
            break

        # Check if any neighbor is already in our set
        can_add = True
        for neighbor in adj[node]:
            if neighbor in indep_set:
                can_add = False
                break

        if can_add:
            indep_set.append(node)
            for neighbor in adj[node]:
                filtered.add(neighbor)

    # Either we have enough, or filter based on actual neighbors
    actual_valid = [x for x in nodes if len([y for y in indep_set if y in adj[x]]) == 0]
    actual_valid.sort(key=lambda x: len(adj[x]))

    final_set = []
    for node in actual_valid:
        if len(final_set) >= target:
            break
        can_add = True
        for neighbor in adj[node]:
            if neighbor in final_set:
                can_add = False
                break
        if can_add:
            final_set.append(node)

    if len(final_set) >= target:
        return "1\n" + " ".join(map(str, final_set[:target]))

    # Fallback: return at least something
    return "1\n" + " ".join(map(str, final_set[:target if len(final_set) >= target else len(final_set)]))

