# Solution for the Cardbluff problem

def solution(input_str):
    # Parse input
    lines = input_str.strip().split('\n')
    first_line = lines[0].split()
    n, k = int(first_line[0]), int(first_line[1])

    a_line = list(map(int, lines[1].split()))
    e_line = list(map(int, lines[2].split()))

    # Compute GCD of all a_i
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    g = a_line[0]
    for x in a_line[1:]:
        g = gcd(g, x)

    if g == 1:
        return "0\n"

    # Factorize g
    def prime_factors_dict(num):
        factors = {}
        d = 2
        while d * d <= num:
            while num % d == 0:
                factors[d] = factors.get(d, 0) + 1
                num //= d
            d += 1
        if num > 1:
            factors[num] = factors.get(num, 0) + 1
        return factors

    prime_factors = prime_factors_dict(g)
    primes = sorted(list(prime_factors.keys()))
    m = len(primes)
    prime_to_idx = {p: i for i, p in enumerate(primes)}

    # If no primes to factorize or g is 1
    if m == 0:
        return "0\n"

    # For each judge, compute their mask of breakable primes
    # Group by (mask, min_e)
    mask_min_e = {}

    for a_i, e_i in zip(a_line, e_line):
        mask = 0
        for p in primes:
            idx = prime_to_idx[p]
            count = 0
            temp = a_i
            while temp % p == 0:
                count += 1
                temp //= p

            if count > 0:
                # Check if p^count <= k without overflow
                p_power = 1
                can_break = True
                for _ in range(count):
                    if k // p < 1:
                        can_break = False
                        break
                    p_power *= p
                if can_break and p_power <= k:
                    mask |= (1 << idx)

        # Group by mask, keeping minimum e
        if mask not in mask_min_e or e_i < mask_min_e[mask]:
            mask_min_e[mask] = e_i

    if not mask_min_e:
        return "-1\n"

    # DP initialization
    INF = float('inf')
    full_mask = (1 << m) - 1
    max_x = m + 1  # We might need x up to m+1 in some cases

    # dp[mask][x] = minimum sum of e to cover 'mask' using exactly 'x' judges
    dp = [[INF] * max_x for _ in range(1 << m)]
    dp[0][0] = 0

    # Process each judge
    for judge_mask, judge_e in mask_min_e.items():
        for mask_j in range(1 << m):
            for x_j in range(max_x - 1):
                if dp[mask_j][x_j] == INF:
                    continue

                new_mask = mask_j | judge_mask
                new_x = x_j + 1

                if new_x < max_x:
                    new_e = dp[mask_j][x_j] + judge_e
                    if new_e < dp[new_mask][new_x]:
                        dp[new_mask][new_x] = new_e

    # Compute the answer
    result = INF
    for x in range(1, max_x):
        if dp[full_mask][x] != INF:
            result = min(result, x * dp[full_mask][x])

    if result == INF:
        return "-1\n"
    else:
        return f"{result}\n"

def digits_to_range(d):
    """Return (start, end) range of numbers with d digits."""
    if d == 1:
        return (1, 9)
    return (10**(d-1), 10**d - 1)

def cnt_len(d):
    """Count of digits contributed by all numbers with exactly d digits."""
    start, end = digits_to_range(d)
    count = end - start + 1  # number of d-digit numbers
    return count * d

def get_len(n):
    """Get the length (number of digits) of n."""
    return len(str(n))

