import os

def solve_case(n, m, roads):
    """
    Solve the Silver Ring problem for given n cities and m roads.

    Returns a string of 'i' and 'o' characters if a valid configuration exists,
    otherwise returns 'Impossible'.
    """

    def crosses(a, b, c, d):
        """Check if intervals (a,b) and (c,d) cross in a ring."""
        # Ensure a < b and c < d is not necessary, but we normalize
        a, b = min(a, b), max(a, b)
        c, d = min(c, d), max(c, d)

        # Check if they are completely disjoint or one contains the other
        # They cross if endpoints alternate
        # For non-crossing, either: both in [1, k] or one in [k, 1]
        # Cross happens when: a < c < b < d or c < a < d < b (considering wraparound)
        return (a < c < b < d) or (c < a < d < b)

    def is_valid_inside(configuration):
        """Check if all 'i' roads don't cross each other."""
        inside_roads = []
        for i, road in enumerate(roads):
            if configuration[i] == 'i':
                inside_roads.append(road)
        for i in range(len(inside_roads)):
            for j in range(i + 1, len(inside_roads)):
                a, b = inside_roads[i][0], inside_roads[i][1]
                c, d = inside_roads[j][0], inside_roads[j][1]
                if crosses(a, b, c, d):
                    return False
        return True

    def is_valid_outside(configuration):
        """Check if all 'o' roads don't cross each other."""
        outside_roads = []
        for i, road in enumerate(roads):
            if configuration[i] == 'o':
                outside_roads.append(road)
        for i in range(len(outside_roads)):
            for j in range(i + 1, len(outside_roads)):
                a, b = outside_roads[i][0], outside_roads[i][1]
                c, d = outside_roads[j][0], outside_roads[j][1]
                if crosses(a, b, c, d):
                    return False
        return True

    def check_configuration(configuration):
        return is_valid_outside(configuration) and is_valid_inside(configuration)

    # Try all 2^m combinations (may be too slow)
    for mask in range(1 << m):
        configuration = []
        for i in range(m):
            configuration.append('i' if (mask >> i) & 1 else 'o')
        if check_configuration(configuration):
            return ''.join(configuration) + '\n'

    return 'Impossible\n'

