import math

def solution(input_data):
    # Parse input
    l, r = map(int, input_data.strip().split())

    # Generate base primes up to sqrt(r) using sieve of Eratosthenes
    limit = int(math.isqrt(r)) + 1
    is_prime_small = [True] * (limit + 1)
    is_prime_small[0] = is_prime_small[1] = False
    for i in range(2, int(math.isqrt(limit)) + 1):
        if is_prime_small[i]:
            for j in range(i*i, limit + 1, i):
                is_prime_small[j] = False
    base_primes = [i for i, valid in enumerate(is_prime_small) if valid]

    count = 0
    # Use a reasonable segment size (minimum 10000 for efficiency)
    segment_size = max(10000, r - l + 1)

    # Process range [l, r] in segments
    start = l
    while start <= r:
        end = min(start + segment_size - 1, r)
        length = end - start + 1

        # Initialize segment as all potentially prime
        is_prime_seg = [True] * length

        # Handle small numbers in first segment specially
        for i in range(min(3, length)):
            num = start + i
            if num < 2:
                is_prime_seg[i] = False
            elif num == 2:
                is_prime_seg[i] = True
            elif num % 2 == 0:
                is_prime_seg[i] = False

        # Sieve out composites in this segment
        for p in base_primes:
            # Skip if p*p > end, as all remaining are primes
            if p * p > end:
                break

            # Find first multiple of p in [start, end] that's >= p*p
            first_multiple = ((start + p - 1) // p) * p
            if first_multiple < p * p:
                first_multiple = p * p

            if first_multiple > end:
                continue

            idx = first_multiple - start
            for j in range(idx, length, p):
                is_prime_seg[j] = False

        # Count numbers that are either 2 or ≡ 1 (mod 4)
        for i in range(length):
            num = start + i
            if is_prime_seg[i]:
                if num == 2 or num % 4 == 1:
                    count += 1

        start = end + 1

    return str(count) + '\n'

