def solve(a, b, k, t):
    """
    Solves the memory-lexa game scoring problem.

    We need to count pairs where sum_Memory > sum_Lexa
    Memory: a + sum_t_values[-k to k], Lexa: b + sum_t_values[-k to k]

    Returns the count modulo 10^9 + 7
    """
    MOD = 1000000007

    max_sum = t * k
    offset = max_sum
    size = 2 * max_sum + 1

    # Initialize DP: dp[i] = ways to get sum (i - offset)
    dp = [0] * size
    dp[offset] = 1

    # Build distribution for one player after t turns
    for turn in range(t):
        new_dp = [0] * size
        for i in range(size):
            if dp[i] == 0:
                continue
            for val in range(-k, k+1):
                idx = i + val
                if 0 <= idx < size:
                    new_dp[idx] = (new_dp[idx] + dp[i]) % MOD
        dp = new_dp

    # Count winning pairs: sum_Memory > sum_Lexa means
    # a + mem_sum > b + lex_sum => lex_sum < a - b + mem_sum

    # Precompute suffix sums for fast range queries
    suffix = [0] * (size + 1)
    for i in range(size - 1, -1, -1):
        suffix[i] = (suffix[i+1] + dp[i]) % MOD

    count = 0
    for i in range(size):
        if dp[i] == 0:
            continue

        mem_sum = i - offset
        lex_max = a - b + mem_sum
        idx_max = lex_max + offset

        if idx_max >= size - 1:
            lex_ways = suffix[0]
        elif idx_max + 1 <= 0:
            lex_ways = 0
        else:
            lex_ways = (suffix[0] - suffix[idx_max + 1]) % MOD

        count = (count + dp[i] * lex_ways) % MOD

    return str(count)


