def solution(input_str):
    """
    Find the shortest path from (1,1) to 'F' accounting for button swaps.
    """
    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    first_line_parts = lines[0].split()

    n = int(first_line_parts[0])
    m = int(first_line_parts[1])

    # Determine if swap parameters are present
    is_swap_lr = int(first_line_parts[2]) if len(first_line_parts) > 2 else 0
    is_swap_ud = int(first_line_parts[3]) if len(first_line_parts) > 3 else 0

    # Parse board
    board = []
    if len(first_line_parts) > 3:
        # Swap info is on first line, board starts at line 1
        for i in range(1, n + 1):
            board.append(lines[i]) if i < len(lines) else board.append("*" * m)
    else:
        # No swap info, board is lines 0 to n-1
        board = lines[:n]

    # Find finish position
    finish_pos = None
    for r in range(n):
        for c in range(m):
            if r < len(board) and c < len(board[r]):
                if board[r][c] == 'F':
                    finish_pos = (r, c)
                    break
        if finish_pos:
            break

    if not finish_pos:
        return ""

    from collections import deque

    def get_direction(label):
        """Get the actual movement for a button press given swaps"""
        if label == 'R':
            if is_swap_lr:
                return (0, -1)
            return (0, 1)
        elif label == 'L':
            if is_swap_lr:
                return (0, 1)
            return (0, -1)
        elif label == 'U':
            if is_swap_ud:
                return (1, 0)
            return (-1, 0)
        elif label == 'D':
            if is_swap_ud:
                return (-1, 0)
            return (1, 0)
        return (0, 0)

    dir_map = {'U': get_direction('U'), 'D': get_direction('D'), 'L': get_direction('L'), 'R': get_direction('R')}

    # BFS from starting position (0, 0)
    queue = deque([(0, 0, "")])
    visited = {(0, 0)}

    while queue:
        r, c, path = queue.popleft()

        if (r, c) == finish_pos:
            return path

        for label, (dr, dc) in dir_map.items():
            nr, nc = r + dr, c + dc

            if (nr, nc) in visited:
                continue

            if not (0 <= nr < n and 0 <= nc < m):
                continue

            # Check if cell is safe (not '*')
            if nr < len(board) and nc < len(board[nr]):
                if board[nr][nc] == '*':
                    continue
            else:
                continue

            visited.add((nr, nc))
            queue.append((nr, nc, path + label))

    return ""

