def solution(input_str):
    """
    Solution for Lena's pairwise maximization problem.
    Uses Li Chao Tree to efficiently handle max(x*q + y) queries.
    """

    # Parse input
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    class LiChaoTree:
        """
        Li Chao Tree for maintaining the upper envelope of lines.
        Each line is y = mx + c
        """
        def __init__(self):
            self.N = 1
            while self.N < 3 * 10 ** 6:
                self.N *= 2
