    perfect_sets = []

    def is_perfect(subset):
        if not subset:
            return False
        s = set(subset)
        # Must contain 0
        if 0 not in s:
            return False
        # Closed under XOR
        for a in s:
            for b in s:
                if (a ^ b) not in s:
                    return False
        return True

    n = k + 1
